import{z as p,x as B,o as E,c as P,q as i,j as n,D as e,d as t,s as o,S as l,b as s}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"ICMP","description":"","frontmatter":{"title":"ICMP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/icmp.md","filePath":"cs/icmp.md","lastUpdated":1791063341000}'),d={name:"cs/icmp.md"};function A(C,a,c,m,I,D){const r=B("Mermaid");return E(),P("div",null,[a[2]||(a[2]=i('<h1 id="icmp" tabindex="-1">ICMP <a class="header-anchor" href="#icmp" aria-label="Permalink to &quot;ICMP&quot;">​</a></h1><div class="epigraph"><p>ICMP 承载网络层的差错与诊断：目的不可达、超时、回显；它不是用户字节流。</p><footer>—— 据 Postel, RFC 792, Internet Control Message Protocol, 1981 整理</footer></div><p><a href="/cs/ip-fragment">上一课</a>可能找不到路由，或 <a href="/cs/ip-subnet">IP</a> 的 TTL 减到零。静默丢包让源主机无法区分「远」与「死」。缺口是 <strong>ICMP</strong>：对源 IP 回控制报文。本课不把 ping 当应用层协议课程，也不引入 DHCP。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>路由器丢包若无信号，传输层只能靠超时猜测。RFC 792：目的不可达（网络/主机/端口等）、超时（TTL）、参数问题、源抑制（历史）、重定向、回显请求/应答。ICMP 封装在 IP 里，协议号 1。缺口不是新的 LPM 规则，而是这些消息的语义与限制：差错报文不要再对差错报文生成，以免风暴。</p><p><span class="marginnote">「差错不再生差错」翻译成大白话：路由器只对用户数据的失败回话；如果回话本身又失败，就保持沉默，让上层超时兜底。否则一次故障会滚雪球成消息风暴——每条 ICMP 又触发新 ICMP，无限套娃。</span></p><p>本课不把 ICMP 当隐蔽信道来讲。</p><p><span class="marginnote">Traceroute 利用 TTL=1,2,… 与超时消息探路径，是诊断工具，不是路由协议。路径上的过滤会使结果残缺。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>转发失败：构造 ICMP，源地址用出接口或路由器地址，目的是原包源地址，载荷含原 IP 头与部分数据以便匹配。主机 ping：回显请求，对端应答。端口不可达常由主机在无监听传输端口时发出，为后课 UDP 预留。</p><p><span class="marginnote">数字实例：差错报文只带原 IP 头加前 8 字节载荷——对 UDP 来说这 8 字节恰好是源/目的端口、长度与校验和，正好够主机把报文对回是哪个 socket。这就是「为什么偏偏是 8 字节」：再多浪费，再少对不上号。</span></p>',11)),(E(),n(l,null,{default:e(()=>[o(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20DROP%5B%22%E4%B8%A2%E5%8C%85%3A%20%E6%97%A0%E8%B7%AF%E7%94%B1%E6%88%96%20TTL%22%5D%20--%3E%20ICMP%5B%22ICMP%20%E5%B7%AE%E9%94%99%E7%BB%99%E6%BA%90%22%5D%0A%20%20ECHO%5B%22%E5%9B%9E%E6%98%BE%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20REP%5B%22%E5%9B%9E%E6%98%BE%E5%BA%94%E7%AD%94%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[t("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,"ICMP 把网络层的失败接到端系统，但仍是尽力而为：ICMP 自己也会丢。端到端论证：应用不能只靠「没收到 ICMP」断定成功。许多站点过滤 ICMP，于是诊断与「路径 MTU 发现」变钝——PMTU 依赖「需要分片」类消息，本课点名，IPv6 课会强调不分片。",-1)),(E(),n(l,null,{default:e(()=>[o(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20B%5B%22%E6%BA%90%E5%8F%91%E8%B6%85%E8%BF%87%20MTU%20%E7%9A%84%E5%8C%85%E4%B8%94%20DF%20%E7%BD%AE%E4%BD%8D%22%5D%20--%3E%20R%5B%22%E8%B7%AF%E7%94%B1%E5%99%A8%E5%9B%9E%E3%80%8E%E9%9C%80%E8%A6%81%E5%88%86%E7%89%87%E3%80%8FICMP%22%5D%0A%20%20R%20--%3E%20F%5B%22%E8%A2%AB%E4%B8%AD%E9%97%B4%E9%98%B2%E7%81%AB%E5%A2%99%E9%9D%99%E9%BB%98%E8%BF%87%E6%BB%A4%22%5D%0A%20%20F%20--%3E%20S%5B%22%E6%BA%90%E6%94%B6%E4%B8%8D%E5%88%B0%EF%BC%8C%E5%8F%AA%E8%83%BD%E5%8F%8D%E5%A4%8D%E9%87%8D%E5%8F%91%E5%90%8C%E6%A0%B7%E7%9A%84%E5%A4%A7%E5%8C%85%22%5D%0A%20%20S%20--%3E%20BH%5B%22%E4%BC%9A%E8%AF%9D%E5%8D%A1%E6%AD%BB%EF%BC%9APMTU%20%E9%BB%91%E6%B4%9E%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<p><span class="marginnote">常见误区：把「ping 不通」当成「网络断了」。回显只是众多 ICMP 类型之一，很多站点单独过滤它、却放行差错报文；反过来 ping 得通也不代表应用可达。诊断要看具体类型，别用一个回合下结论。</span></p><p>与<a href="/cs/signals">信号</a>类比：都是异步通知，但 ICMP 走网络，对象是 IP 端点不是 PID。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 ICMPv6 的全部类型列完（邻居发现在 IPv6 课）。不引入 ICMP 重定向作为默认安全实践——可被滥用，主机常忽略。地址如何自动配置、私网如何共享公网地址，下一课 DHCP 与 NAT。</p><p>源抑制在当代拥塞控制里已废弃，不应再依赖。重定向把主机的 LPM 改向，错误配置会把流量拐走，许多系统默认忽略。</p><p>回显与差错共用协议号，过滤策略要分开看类型。</p><p>后课默认：网络层可用 ICMP 报告失败与回显。地址分配与公私网边界，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ICMP（RFC 792）报告不可达、超时，并提供回显。</li><li>不为差错再发差错；诊断可被过滤。</li><li>地址配置与 NAT 是下一课。</li><li>出处：RFC 792；Kurose and Ross。</li></ul>',9))])}const h=p(d,[["render",A]]);export{T as __pageData,h as default};
